def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_op = opp[-1]
    last_me = me[-1]

    if n < 4:
        if last_op == 'D' and n >= 2 and opp[-2] == 'D':
            return 'D'
        return 'C'

    opp_d = sum(1 for a in opp if a == 'D')
    opp_c = n - opp_d

    if opp_d == 0:
        if n >= 97:
            return 'D'
        if n >= 90 and rng.random() < 0.3:
            return 'D'
        return 'C'

    streak = 0
    for a in reversed(opp):
        if a == 'D':
            streak += 1
        else:
            break

    win = min(15, n)
    recent = opp[-win:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_rate = recent_c / float(win)

    if streak >= 3:
        if recent_rate < 0.2:
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if last_op == 'D':
        if streak == 1 and recent_rate > 0.4:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'

    if n >= 97:
        return 'D'
    if n >= 93:
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    if opp_d == 1 and n >= 6 and last_op == 'C':
        return 'C'

    if recent_rate >= 0.8:
        if n >= 80 and rng.random() < 0.2:
            return 'D'
        if rng.random() < 0.04:
            return 'D'
        return 'C'

    if recent_rate >= 0.5:
        if last_me == 'D' and last_op == 'C':
            return 'C'
        if rng.random() < 0.1:
            return 'D'
        return 'C'

    if opp_c == 0:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    if rng.random() < 0.3:
        return 'C'
    return 'D'
